/**
 * The Thesis-Driven Essay's slide decks, one per lesson of Brian's course.
 *
 * The decks are generated by scripts/thesis-essay-decks and live as files in
 * resources/thesis-essay-decks. On the assignment type's page each deck hangs
 * off the step it teaches (Pre-writing, Thesis Statement, ...), matched by the
 * step's title: nothing in the schema links a step to a lesson. Day 1 has no
 * step of its own (its "Welcome" module was retired), so it has its own slot.
 */

export interface ThesisEssayDeck {
  /** Its address and file name: resources/thesis-essay-decks/<slug>.pptx. */
  slug: string;
  lesson: number;
  /** What the lesson is called in the course. */
  title: string;
  /** The file name a teacher's download gets. */
  downloadName: string;
  /** Normalized titles of the assignment steps this deck teaches. */
  stepTitles: string[];
}

export const PPTX_CONTENT_TYPE =
  'application/vnd.openxmlformats-officedocument.presentationml.presentation';
export const PDF_CONTENT_TYPE = 'application/pdf';

/**
 * A file a teacher can download from the Modules: a lesson's deck, its
 * lesson plan, or one of the Day 1 student handouts. All are generated
 * together by scripts/thesis-essay-decks, so a plan's slide numbers match
 * its deck.
 */
export interface ThesisEssayMaterial {
  /** Its address: /api/thesis-essay-deck/<slug>. */
  slug: string;
  kind: 'deck' | 'lesson-plan' | 'handout';
  /** Its file in resources/thesis-essay-decks. */
  fileName: string;
  downloadName: string;
  contentType: string;
  /** A handout's link text in the Modules (decks and plans are named by lesson). */
  label?: string;
}

