export const DAY_ONE_DECK = THESIS_ESSAY_DECKS[0];

/** Lowercase, hyphens and punctuation dropped, spaces collapsed. */
function normalizeTitle(title: string): string {
  return title
    .toLowerCase()
    .replace(/-/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** The deck for an assignment step, by the step's title, if it has one. */
export function deckForModuleTitle(title: string): ThesisEssayDeck | null {
  const normalized = normalizeTitle(title);
  if (!normalized) return null;
  return THESIS_ESSAY_DECKS.find((deck) => deck.stepTitles.includes(normalized)) ?? null;
}

export function deckBySlug(slug: string): ThesisEssayDeck | null {
  return THESIS_ESSAY_DECKS.find((deck) => deck.slug === slug) ?? null;
}

export function deckMaterial(deck: ThesisEssayDeck): ThesisEssayMaterial {
  return {
    slug: deck.slug,
    kind: 'deck',
    fileName: `${deck.slug}.pptx`,
    downloadName: deck.downloadName,
    contentType: PPTX_CONTENT_TYPE,
  };
}

/** The lesson plan that goes with a deck: same lesson, same slide numbers. */
export function lessonPlanMaterial(deck: ThesisEssayDeck): ThesisEssayMaterial {
  return {
    slug: `${deck.slug}-lesson-plan`,
    kind: 'lesson-plan',
    fileName: `${deck.slug}-lesson-plan.pdf`,
    downloadName: deck.downloadName.replace(/\.pptx$/, ' - Lesson Plan.pdf'),
    contentType: PDF_CONTENT_TYPE,
  };
}

