const DAY_ONE_HANDOUTS = [SIGN_UP_HANDOUT, SAMPLE_ESSAY_HANDOUT];

export const THESIS_ESSAY_MATERIALS: readonly ThesisEssayMaterial[] = [
  ...THESIS_ESSAY_DECKS.flatMap((deck) => [deckMaterial(deck), lessonPlanMaterial(deck)]),
  ...DAY_ONE_HANDOUTS,
];

/** What a step offers, in order: its deck, its lesson plan (and Day 1's handouts). */
export function materialsForDeck(deck: ThesisEssayDeck): ThesisEssayMaterial[] {
  const materials = [deckMaterial(deck), lessonPlanMaterial(deck)];
  return deck === DAY_ONE_DECK ? [...materials, ...DAY_ONE_HANDOUTS] : materials;
}

export function materialBySlug(slug: string): ThesisEssayMaterial | null {
  return THESIS_ESSAY_MATERIALS.find((material) => material.slug === slug) ?? null;
}

export function materialHref(material: ThesisEssayMaterial): string {
  return `/api/thesis-essay-deck/${material.slug}`;
}

export function deckHref(deck: ThesisEssayDeck): string {
  return materialHref(deckMaterial(deck));
}

/** What the page shows for a deck: "Lesson 3 · Thesis Statement". */
export function deckLabel(deck: ThesisEssayDeck): string {
  return `Lesson ${deck.lesson} · ${deck.title}`;
}

// ---------------------------------------------------------------------------
// The three ways to use a deck: present it on YAWP!, copy it into Google
// Slides, or download it for PowerPoint (`deckHref`).

/** Where a teacher presents a deck on YAWP!, exactly as designed. */
export function presentHref(deck: ThesisEssayDeck): string {
  return `/present/thesis-essay/${deck.slug}`;
}

/**
 * Each deck's master copy in Google Slides, by slug: checked by hand in
 * Google Slides and shared "anyone with the link can view". A deck without
 * one offers no Google Slides button.
 */
export const GOOGLE_SLIDES_COPY_IDS: Readonly<Record<string, string>> = {};

/** Google's "Make a copy" page for a deck's master copy, or null when there is none. */
export function googleSlidesCopyHref(
  deck: ThesisEssayDeck,
  ids: Readonly<Record<string, string>> = GOOGLE_SLIDES_COPY_IDS
): string | null {
  const id = Object.hasOwn(ids, deck.slug) ? ids[deck.slug] : '';
  return /^[A-Za-z0-9_-]+$/.test(id) ? `https://docs.google.com/presentation/d/${id}/copy` : null;
}

const ASSET_TYPES: Record<string, string> = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg' };

/** An image or icon the presenter draws: `name.png`, or `icons/name.png`. Nothing else. */
export function isDeckAssetName(name: string): boolean {
  return /^(icons\/)?[a-z0-9-]+\.(png|jpe?g)$/.test(name);
}

export function deckAssetContentType(name: string): string {
  return ASSET_TYPES[name.split('.').pop() ?? ''] ?? 'application/octet-stream';
}

/** Where the presenter loads a deck image from. */
export function deckAssetHref(name: string): string {
  return `/api/thesis-essay-deck-asset/${name}`;
}

/**
 * The deck for a module of the Faculty Lounge's Trainings: in the
 * Thesis-Driven Essay course, "Lesson 3: Developing a Thesis Statement" is
 * Lesson 3's deck. Trainings name their modules by lesson number, not by the
 * assignment's step titles.
 */
export function deckForTrainingModule(courseTitle: string, moduleTitle: string): ThesisEssayDeck | null {
  if (normalizeTitle(courseTitle).replace(/^the /, '') !== 'thesisdriven essay') return null;
  const lesson = /^\s*lesson\s+(\d+)\s*:/i.exec(moduleTitle);
  if (!lesson) return null;
  return THESIS_ESSAY_DECKS.find((deck) => deck.lesson === Number(lesson[1])) ?? null;
}

/** One button under a lesson: a way to use its deck, its lesson plan, or a handout. */
export interface ThesisDeckLink {
  kind: ThesisEssayMaterial['kind'] | 'present' | 'google-slides';
  label: string;
  href: string;
}

/**
 * A lesson's buttons, in order: present its deck on YAWP!, copy it into
 * Google Slides, download it for PowerPoint, its lesson plan, then any
 * handouts. Only what is there: `available` material slugs on disk,
 * `presentable` decks with a scene, and a Google master copy. Presenting
 * returns to `returnTo` when the teacher closes it.
 */
export function deckLinks(
  deck: ThesisEssayDeck,
  {
    available,
    presentable,
    returnTo,
    googleIds = GOOGLE_SLIDES_COPY_IDS,
  }: {
    available: ReadonlySet<string>;
    presentable: ReadonlySet<string>;
    returnTo: string;
    googleIds?: Readonly<Record<string, string>>;
  }
): ThesisDeckLink[] {
  const label = deckLabel(deck);
  const google = googleSlidesCopyHref(deck, googleIds);
  return [
    ...(presentable.has(deck.slug)
      ? [{ kind: 'present' as const, label, href: `${presentHref(deck)}?from=${encodeURIComponent(returnTo)}` }]
      : []),
    ...(google ? [{ kind: 'google-slides' as const, label, href: google }] : []),
    ...materialsForDeck(deck)
      .filter((material) => available.has(material.slug))
      .map((material) => ({ kind: material.kind, label: material.label ?? label, href: materialHref(material) })),
  ];
}
